query NamespaceHealth {
  lms { namespace status }
  lcms { namespace status }
  crm { namespace status }
  elearning { namespace status }
}

query LmsClassWorkspace($input: ClassWorkspaceInput!) {
  lms {
    classWorkspace(input: $input) {
      tenantId
      classInfo { id schoolId name grade academicYear status studentCount assignmentCount }
      scoreSummary { completedAttemptCount attemptedStudentCount averagePercent bestPercent }
      riskSummary { missingOverdueStudentCount lowScoreStudentCount inactiveStudentCount }
      students { page size totalItems items { id studentCode fullName authUserId status } }
      assignments { page size totalItems items { id academicClassId quizId subjectId status dueAt assignedBy } }
    }
  }
}

query TeacherHomeworkWorkspace($input: TeacherHomeworkWorkspaceInput) {
  lms {
    teacherHomeworkWorkspace(input: $input) {
      tenantId
      teacherId
      summary { activeAssignmentCount overdueAssignmentCount pendingReviewAssignmentCount }
      classOptions { id schoolId name grade academicYear status }
      assignments { page size totalItems items { id academicClassId quizId subjectId status dueAt assignedBy } }
      pendingReviews { totalItems items { attemptId assignmentId studentId studentCode fullName status percent } }
      overdueStudents { totalItems items { assignmentId studentId studentCode fullName dueAt } }
    }
  }
}

query AssignmentProgressWorkspace($input: AssignmentProgressWorkspaceInput!) {
  lms {
    assignmentProgressWorkspace(input: $input) {
      tenantId
      assignment { id academicClassId quizId subjectId status dueAt assignedBy recipientMode }
      summary { submittedCount inProgressCount needsReviewCount }
      attempts { page size totalItems items { id studentId status score maxScore percent submittedAt } }
      recipients { page size totalItems items { studentId studentCode fullName status missing late latestAttempt { id percent status } bestAttempt { id percent status } } }
      missingLateStudents { totalItems items { studentId studentCode fullName missing late dueAt } }
    }
  }
}

query LearningResourceLibrary($input: LearningResourceLibraryInput) {
  lms {
    learningResourceLibrary(input: $input) {
      tenantId
      educationUnitId
      taxonomyTree { id kind label slug parentId childCount resourceCount }
      resources { page size totalItems items { id title slug subjectId categoryId sectionId visibility status thumbnailUrl } }
      progress { resourceId progressRate updatedAt }
      recentOpened { resourceId title openedAt }
    }
  }
}

query QuestionBankWorkspace($input: QuestionBankWorkspaceInput) {
  lcms {
    questionBankWorkspace(input: $input) {
      tenantId
      questions { page size totalItems items { id subjectId levelId topicId title type status usageCount } }
      subjects { id label }
      levels { id label }
      topics { id label }
      quizzes { id title status }
    }
  }
}

query AccessManagementWorkspace($input: AccessManagementWorkspaceInput) {
  lcms {
    accessManagementWorkspace(input: $input) {
      tenantId
      users { page size totalItems items { userId fullName email status roleCount scopeCount effectivePermissions { permission source } } }
      roleOptions { id name }
      scopeOptions { id label kind }
      effectivePermissionsIncluded
    }
  }
}

query StudentDashboard($input: StudentDashboardInput) {
  elearning {
    studentDashboard(input: $input) {
      tenantId
      viewer { userId tenantId accountType accessLevel }
      profile { userId studentId studentCode fullName email schoolId academicClassId status updatedAt }
      summary { enrolledCourseCount activeAssignmentCount pendingActionCount generatedAt scoreSummary { completedAttemptCount attemptedAssignmentCount passedAttemptCount averagePercent bestPercent } }
      courses { id title status progressPercent updatedAt }
      assignments { id title status dueAt }
      nextActions { id kind label targetId dueAt }
      announcements { id title content pinned publishedAt updatedAt }
    }
  }
}

